use xiom.io;
type Recipe = {
  servings: Int;
  flour_cups: Int;
  sugar_cups: Int;
  eggs: Int;
}

fn scale_recipe(original: &Recipe, new_servings: Int) -> Recipe {
  let ratio = new_servings / original.servings;
  Recipe{
    servings: new_servings,
    flour_cups: original.flour_cups * ratio,
    sugar_cups: original.sugar_cups * ratio,
    eggs: original.eggs * ratio
  }
}

fn main() -> Int {
  let original = Recipe{ servings: 12, flour_cups: 2, sugar_cups: 1, eggs: 2 };
  let scaled = scale_recipe(&original, 30);
  io.println(scaled.flour_cups.to_str());
  io.println(scaled.sugar_cups.to_str());
  io.println(scaled.eggs.to_str());
  return 0;
}
